+using System.Net.Http.Headers;
+using System.Text;
+using System.Text.Json;
+
+namespace JobTrack.Cli;
+
+public interface IJobTrackApiClient
+{
+    Task<IJobTrackReadData> ListTasksAsync(
+        string? projectId = null,
+        string? status = null,
+        string? assignee = null,
+        string? priority = null,
+        CancellationToken cancellationToken = default);
+
+    Task<IJobTrackReadData> ListTaskCommentsAsync(string taskId, CancellationToken cancellationToken = default);
+
+    Task<IJobTrackReadData> ListProjectsAsync(CancellationToken cancellationToken = default);
+
+    Task<IJobTrackReadData> GetAuthenticatedPrincipalAsync(CancellationToken cancellationToken = default);
+}
+
+public class JobTrackClientException : Exception
+{
+    public JobTrackClientException(
+        string message,
+        IJobTrackReadData? details = null,
+        Exception? innerException = null)
+        : this(message, details, commandMessagePrefix: null, innerException)
+    {
+    }
+
+    protected JobTrackClientException(
+        string message,
+        IJobTrackReadData? details,
+        string? commandMessagePrefix,
+        Exception? innerException)
+        : base(message, innerException)
+    {
+        Details = details ?? JobTrackReadData.Empty;
+        CommandMessagePrefix = commandMessagePrefix;
+    }
+
+    public IJobTrackReadData Details { get; }
+
+    private string? CommandMessagePrefix { get; }
+
+    public string FormatCommandMessage(string commandName)
+    {
+        var message = string.IsNullOrWhiteSpace(CommandMessagePrefix)
+            ? Message
+            : $"{CommandMessagePrefix}: {Message}";
+        return $"jt {commandName}: {message}";
+    }
+}
+
+public sealed class JobTrackApiException : JobTrackClientException
+{
+    public JobTrackApiException(string message, IJobTrackReadData? details = null)
+        : base(message, details: details)
+    {
+    }
+}
+
+public sealed class JobTrackApiRequestException : JobTrackClientException
+{
+    public JobTrackApiRequestException(string message, Exception innerException)
+        : base(message, details: null, commandMessagePrefix: "request failed", innerException: innerException)
+    {
+    }
+}
+
+public sealed class JobTrackConfigurationException : JobTrackClientException
+{
+    public JobTrackConfigurationException(string message)
+        : base(message)
+    {
+    }
+}
+
+public sealed class JobTrackApiResponseException : JobTrackClientException
+{
+    public JobTrackApiResponseException(string message, Exception? innerException = null)
+        : base(message, innerException: innerException)
+    {
+    }
+}
+
+public sealed class JobTrackApiClient : IJobTrackApiClient
+{
+    private const string ApiUrlEnv = "JOBTRACK_API_URL";
+    private const string ApiKeyEnv = "JOBTRACK_API_KEY";
+    // A 4 MiB response keeps list commands responsive while allowing thousands of compact task rows.
+    private const int MaxResponseBytes = 4 * 1024 * 1024;
+    private const int ResponseReadBufferBytes = 81920; // Matches Stream.CopyTo's default buffer size.
+
+    private readonly record struct QueryParameter(string Name, string? Value);
+
+    private readonly HttpMessageHandler? _handler;
+
+    public JobTrackApiClient()
+    {
+    }
+
+    internal JobTrackApiClient(HttpMessageHandler handler)
+    {
+        _handler = handler ?? throw new ArgumentNullException(nameof(handler));
+    }
+
+    public Task<IJobTrackReadData> ListTasksAsync(
+        string? projectId = null,
+        string? status = null,
+        string? assignee = null,
+        string? priority = null,
+        CancellationToken cancellationToken = default)
+    {
+        var parameters = new[]
+        {
+            new QueryParameter("projectId", projectId),
+            new QueryParameter("status", status),
+            new QueryParameter("assignee", assignee),
+            new QueryParameter("priority", priority)
+        };
+
+        return GetDataAsync("/api/tasks", parameters, cancellationToken);
+    }
+
+    public Task<IJobTrackReadData> ListTaskCommentsAsync(string taskId, CancellationToken cancellationToken = default)
+    {
+        var path = $"/api/tasks/{Uri.EscapeDataString(taskId)}/comments";
+        return GetDataAsync(path, Array.Empty<QueryParameter>(), cancellationToken);
+    }
+
+    public Task<IJobTrackReadData> ListProjectsAsync(CancellationToken cancellationToken = default)
+    {
+        return GetDataAsync("/api/projects", Array.Empty<QueryParameter>(), cancellationToken);
+    }
+
+    public Task<IJobTrackReadData> GetAuthenticatedPrincipalAsync(CancellationToken cancellationToken = default)
+    {
+        return GetDataAsync("/api/auth/me", Array.Empty<QueryParameter>(), cancellationToken);
+    }
+
+    private async Task<IJobTrackReadData> GetDataAsync(
+        string path,
+        IReadOnlyList<QueryParameter> query,
+        CancellationToken cancellationToken = default)
+    {
+        var (baseUri, key) = ReadEnv();
+        using var http = NewClient(baseUri, key);
+
+        try
+        {
+            using var response = await http.GetAsync(BuildPath(path, query), HttpCompletionOption.ResponseHeadersRead, cancellationToken);
+            var body = await ReadContentAsync(response.Content, cancellationToken);
+
+            if (!response.IsSuccessStatusCode)
+            {
+                throw new JobTrackApiException(
+                    FormatFailureMessage(response),
+                    BuildFailureDetails(response, body));
+            }
+
+            return ParseResponseBody(body);
+        }
+        catch (Exception ex) when (ex is HttpRequestException or IOException)
+        {
+            throw new JobTrackApiRequestException(ex.Message, ex);
+        }
+    }
+
+    private static string FormatFailureMessage(HttpResponseMessage response)
+    {
+        var status = $"HTTP {(int)response.StatusCode}";
+        return string.IsNullOrWhiteSpace(response.ReasonPhrase)
+            ? status
+            : $"{status} {response.ReasonPhrase}";
+    }
+
+    private static IJobTrackReadData BuildFailureDetails(HttpResponseMessage response, string body)
+    {
+        var details = new Dictionary<string, object?>(StringComparer.Ordinal);
+
+        if (!string.IsNullOrWhiteSpace(response.ReasonPhrase))
+        {
+            details["reason"] = response.ReasonPhrase;
+        }
+
+        if (!string.IsNullOrWhiteSpace(body))
+        {
+            details["detail"] = ReadStructuredDetail(body);
+        }
+
+        return details.Count == 0
+            ? JobTrackReadData.Empty
+            : JobTrackReadData.FromJson(JsonSerializer.Serialize(details));
+    }
+
+    private static object ReadStructuredDetail(string body)
+    {
+        try
+        {
+            using var document = JsonDocument.Parse(body);
+            return document.RootElement.Clone();
+        }
+        catch (JsonException)
+        {
+            return body;
+        }
+    }
+
+    private static IJobTrackReadData ParseResponseBody(string body)
+    {
+        if (string.IsNullOrWhiteSpace(body))
+        {
+            return JobTrackReadData.Empty;
+        }
+
+        try
+        {
+            return JobTrackReadData.FromJson(body);
+        }
+        catch (JsonException ex)
+        {
+            throw new JobTrackApiResponseException($"JobTrack API response was not valid JSON: {ex.Message}", ex);
+        }
+    }
+
+    private static async Task<string> ReadContentAsync(HttpContent content, CancellationToken cancellationToken)
+    {
+        if (content.Headers.ContentLength is > MaxResponseBytes)
+        {
+            throw new JobTrackApiResponseException($"JobTrack API response exceeded {MaxResponseBytes} bytes");
+        }
+
+        await using var responseStream = await content.ReadAsStreamAsync(cancellationToken);
+        using var buffer = new MemoryStream();
+        var chunk = new byte[ResponseReadBufferBytes];
+
+        while (true)
+        {
+            var read = await responseStream.ReadAsync(chunk, cancellationToken);
+            if (read == 0)
+            {
+                break;
+            }
+
+            if (buffer.Length + read > MaxResponseBytes)
+            {
+                throw new JobTrackApiResponseException($"JobTrack API response exceeded {MaxResponseBytes} bytes");
+            }
+
+            buffer.Write(chunk, 0, read);
+        }
+
+        return Encoding.UTF8.GetString(buffer.ToArray());
+    }
+
+    private static string BuildPath(string path, IReadOnlyList<QueryParameter> query)
+    {
+        var pairs = query
+            .Where(parameter => !string.IsNullOrWhiteSpace(parameter.Value))
+            .Select(parameter => $"{Encode(parameter.Name)}={Encode(parameter.Value!)}")
+            .ToArray();
+
+        return pairs.Length == 0 ? path : $"{path}?{string.Join("&", pairs)}";
+    }
+
+    private static (Uri BaseUri, string Key) ReadEnv()
+    {
+        var url = Environment.GetEnvironmentVariable(ApiUrlEnv);
+        var key = Environment.GetEnvironmentVariable(ApiKeyEnv);
+
+        if (string.IsNullOrWhiteSpace(url))
+        {
+            throw new JobTrackConfigurationException($"{ApiUrlEnv} must be set (e.g. https://jobtrack.example.com or http://localhost:5000)");
+        }
+
+        if (string.IsNullOrWhiteSpace(key))
+        {
+            throw new JobTrackConfigurationException($"{ApiKeyEnv} must be set");
+        }
+
+        var trimmedUrl = url.Trim().TrimEnd('/');
+        if (!Uri.TryCreate(trimmedUrl, UriKind.Absolute, out var baseUri) ||
+            (baseUri.Scheme != Uri.UriSchemeHttps && baseUri.Scheme != Uri.UriSchemeHttp))
+        {
+            throw new JobTrackConfigurationException($"{ApiUrlEnv} must be an absolute http or https URL");
+        }
+
+        if (baseUri.Scheme == Uri.UriSchemeHttp && !baseUri.IsLoopback)
+        {
+            throw new JobTrackConfigurationException($"{ApiUrlEnv} must use https unless it points to localhost for development");
+        }
+
+        return (baseUri, key.Trim());
+    }
+
+    private HttpClient NewClient(Uri baseUri, string key)
+    {
+        var http = _handler is null
+            ? new HttpClient()
+            : new HttpClient(_handler, disposeHandler: false);
+
+        http.BaseAddress = baseUri;
+        http.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", key);
+        http.DefaultRequestHeaders.UserAgent.ParseAdd("jt/0.1");
+        return http;
+    }
+
+    private static string Encode(string value) => Uri.EscapeDataString(value);
+}
