+using System.ComponentModel;
+using System.Text;
+using System.Text.Json;
+using Spectre.Console;
+using Spectre.Console.Cli;
+
+namespace JobTrack.Cli;
+
+public enum OutputFormat
+{
+    Table,
+    Json,
+    Csv
+}
+
+internal sealed record JobTrackDataRows(IReadOnlyList<string> Headers, IReadOnlyList<IReadOnlyList<string>> Rows)
+{
+    public static JobTrackDataRows Empty { get; } = new(Array.Empty<string>(), Array.Empty<IReadOnlyList<string>>());
+}
+
+public abstract class OutputSettings : CommandSettings
+{
+    [CommandOption("-o|--output <FORMAT>")]
+    [Description("Output format.")]
+    public string Output { get; set; } = "table";
+
+    public OutputFormat OutputFormat => TryParseOutput(Output, out var output)
+        ? output
+        : throw new InvalidOperationException(InvalidOutputMessage);
+
+    public override ValidationResult Validate()
+    {
+        var error = GetOutputValidationError();
+        return error is null ? ValidationResult.Success() : ValidationResult.Error(error);
+    }
+
+    protected static string? GetOutputValidationError(string? output)
+    {
+        return TryParseOutput(output, out _)
+            ? null
+            : InvalidOutputMessage;
+    }
+
+    protected string? GetOutputValidationError() => GetOutputValidationError(Output);
+
+    private static bool TryParseOutput(string? value, out OutputFormat output)
+    {
+        return EnumOptionParser.TryParseDefinedName(value, out output);
+    }
+
+    private static string InvalidOutputMessage =>
+        $"--output must be one of: {EnumOptionParser.AllowedNames<OutputFormat>().ToLowerInvariant()}.";
+}
+
+public static class OutputFormatter
+{
+    // Caps padding so one long field does not push adjacent columns beyond common terminal widths.
+    private const int MaxTablePaddingWidth = 120;
+
+    private static readonly JsonWriterOptions JsonOutputOptions = new()
+    {
+        Indented = true
+    };
+
+    public static string FormatApiData(IJobTrackReadData data, OutputFormat format)
+    {
+        return format switch
+        {
+            OutputFormat.Table => data.IsEmpty ? string.Empty : ToTable(ToRows(data)),
+            OutputFormat.Json => data.IsEmpty ? string.Empty : ToJson(data),
+            OutputFormat.Csv => data.IsEmpty ? string.Empty : ToCsv(ToRows(data)),
+            _ => throw UnsupportedOutputFormat(format)
+        };
+    }
+
+    private static ArgumentOutOfRangeException UnsupportedOutputFormat(OutputFormat format)
+    {
+        return new ArgumentOutOfRangeException(nameof(format), format, "Unsupported output format.");
+    }
+
+    private static string ToJson(IJobTrackReadData data)
+    {
+        using var stream = new MemoryStream();
+        using (var writer = new Utf8JsonWriter(stream, JsonOutputOptions))
+        {
+            WriteJsonTo(data, writer);
+        }
+
+        return Encoding.UTF8.GetString(stream.ToArray());
+    }
+
+    private static void WriteJsonTo(IJobTrackReadData data, Utf8JsonWriter writer)
+    {
+        switch (data.Kind)
+        {
+            case JobTrackReadDataKind.Json:
+                using (var document = JsonDocument.Parse(data.Content))
+                {
+                    document.RootElement.WriteTo(writer);
+                }
+
+                return;
+            case JobTrackReadDataKind.Text:
+                writer.WriteStringValue(data.Content);
+                return;
+            case JobTrackReadDataKind.Empty:
+                writer.WriteNullValue();
+                return;
+            default:
+                throw new ArgumentOutOfRangeException(nameof(data), data.Kind, "Unsupported JobTrack read data kind.");
+        }
+    }
+
+    private static JobTrackDataRows ToRows(IJobTrackReadData data)
+    {
+        return data.Kind switch
+        {
+            JobTrackReadDataKind.Json => RowsFromJson(data.Content),
+            JobTrackReadDataKind.Text => TextRows(data.Content),
+            JobTrackReadDataKind.Empty => JobTrackDataRows.Empty,
+            _ => throw new ArgumentOutOfRangeException(nameof(data), data.Kind, "Unsupported JobTrack read data kind.")
+        };
+    }
+
+    private static JobTrackDataRows TextRows(string text)
+    {
+        return new JobTrackDataRows(
+            new[] { "value" },
+            new[] { (IReadOnlyList<string>)new[] { text } });
+    }
+
+    private static JobTrackDataRows RowsFromJson(string json)
+    {
+        using var document = JsonDocument.Parse(json);
+        var root = document.RootElement;
+        var headers = new List<string>();
+        var maps = new List<Dictionary<string, string>>();
+
+        if (root.ValueKind == JsonValueKind.Array)
+        {
+            foreach (var item in root.EnumerateArray())
+            {
+                maps.Add(ReadRow(item, headers));
+            }
+        }
+        else
+        {
+            maps.Add(ReadRow(root, headers));
+        }
+
+        if (headers.Count == 0)
+        {
+            return JobTrackDataRows.Empty;
+        }
+
+        var rows = maps
+            .Select(map => (IReadOnlyList<string>)headers.Select(header => map.GetValueOrDefault(header, string.Empty)).ToArray())
+            .ToArray();
+
+        return new JobTrackDataRows(headers, rows);
+    }
+
+    private static Dictionary<string, string> ReadRow(JsonElement element, List<string> headers)
+    {
+        var row = new Dictionary<string, string>(StringComparer.Ordinal);
+
+        if (element.ValueKind == JsonValueKind.Object)
+        {
+            foreach (var property in element.EnumerateObject())
+            {
+                AddHeader(headers, property.Name);
+                row[property.Name] = ValueToString(property.Value);
+            }
+        }
+        else
+        {
+            AddHeader(headers, "value");
+            row["value"] = ValueToString(element);
+        }
+
+        return row;
+    }
+
+    private static void AddHeader(List<string> headers, string header)
+    {
+        if (!headers.Contains(header, StringComparer.Ordinal))
+        {
+            headers.Add(header);
+        }
+    }
+
+    private static string ValueToString(JsonElement value)
+    {
+        return value.ValueKind switch
+        {
+            JsonValueKind.String => value.GetString() ?? string.Empty,
+            JsonValueKind.Number => value.GetRawText(),
+            JsonValueKind.True => "true",
+            JsonValueKind.False => "false",
+            JsonValueKind.Null => string.Empty,
+            JsonValueKind.Undefined => string.Empty,
+            _ => JsonSerializer.Serialize(value)
+        };
+    }
+
+    private static string ToTable(JobTrackDataRows data)
+    {
+        if (data.Headers.Count == 0)
+        {
+            return string.Empty;
+        }
+
+        var headers = data.Headers.Select(EscapeTableCell).ToArray();
+        var rows = data.Rows
+            .Select(row => (IReadOnlyList<string>)row.Select(EscapeTableCell).ToArray())
+            .ToArray();
+        var widths = headers
+            .Select((header, index) =>
+                Math.Min(
+                    MaxTablePaddingWidth,
+                    Math.Max(header.Length, rows.Select(row => row[index].Length).DefaultIfEmpty(0).Max())))
+            .ToArray();
+
+        var lines = new List<string> { FormatTableRow(headers, widths) };
+        lines.AddRange(rows.Select(row => FormatTableRow(row, widths)));
+        return string.Join(Environment.NewLine, lines);
+    }
+
+    private static string FormatTableRow(IReadOnlyList<string> values, IReadOnlyList<int> widths)
+    {
+        var padded = values.Select((value, index) => value.PadRight(widths[index]));
+        return string.Join("  ", padded).TrimEnd();
+    }
+
+    private static string EscapeTableCell(string value)
+    {
+        return EscapeControlCharacters(value, escapeBackslash: true);
+    }
+
+    private static string EscapeControlCharacters(string value, bool escapeBackslash)
+    {
+        var builder = new StringBuilder(value.Length);
+        foreach (var character in value)
+        {
+            builder.Append(character switch
+            {
+                '\\' when escapeBackslash => "\\\\",
+                '\r' => "\\r",
+                '\n' => "\\n",
+                '\t' => "\\t",
+                _ when IsControlCharacter(character) => $"\…9400 tokens truncated…utputFormat.Csv);
+
+        var expected = string.Join(
+            Environment.NewLine,
+            "title,comment",
+            "\"fix, test\",\"hello, world\"");
+        Assert.Equal(expected, output);
+    }
+
+    [Fact]
+    public void OutputFormatterDoublesEmbeddedCsvQuotes()
+    {
+        var output = OutputFormatter.FormatApiData(
+            ApiData("""[{"title":"say \"hello\"","comment":"quoted, \"value\""}]"""),
+            OutputFormat.Csv);
+
+        var expected = string.Join(
+            Environment.NewLine,
+            "title,comment",
+            "\"say \"\"hello\"\"\",\"quoted, \"\"value\"\"\"");
+        Assert.Equal(expected, output);
+    }
+
+    [Fact]
+    public void OutputFormatterNeutralizesCsvFormulaCells()
+    {
+        var output = OutputFormatter.FormatApiData(
+            ApiData(
+                """
+                [{"equal":"=1","plus":"+1","minus":"-1","at":"@cmd","space":"  -1","tab":"\t@cmd","safe":"text"}]
+                """),
