+            OutputFormat.Csv);
+
+        Assert.Equal(-1, output.IndexOf('\u001B'));
+        Assert.Equal(-1, output.IndexOf('\u0007'));
+        Assert.Equal(-1, output.IndexOf('\u0085'));
