+    }
+
+    [Fact]
+    public void OutputFormatterCapsTablePaddingWidth()
+    {
+        var output = OutputFormatter.FormatApiData(
+            ApiData(
+                $$"""
+                [
+                  {"title":"{{new string('x', 500)}}","status":"Open"},
+                  {"title":"small","status":"Done"}
+                ]
+                """),
+            OutputFormat.Table);
+
+        var lines = output.Split(Environment.NewLine);
