+    }
+
+    [Fact]
+    public void OutputFormatterRejectsUnsupportedOutputFormats()
+    {
+        var unsupported = (OutputFormat)99;
+
+        Assert.Throws<ArgumentOutOfRangeException>(
+            () => OutputFormatter.FormatApiData(ApiData(TaskRowsJson), unsupported));
+    }
+
+    [Fact]
+    public async Task ListCommandsHonorShortOutputAlias()
