+namespace JobTrack.Cli;
+
+internal static class EnumOptionParser
+{
+    public static string AllowedNames<TEnum>()
+        where TEnum : struct, Enum
+    {
+        return string.Join(", ", Enum.GetNames<TEnum>());
+    }
+
+    public static bool TryParseDefinedName<TEnum>(string? value, out TEnum parsed)
+        where TEnum : struct, Enum
+    {
+        parsed = default;
+        if (string.IsNullOrWhiteSpace(value))
+        {
+            return false;
+        }
+
+        var trimmed = value.Trim();
+        var definedName = Enum.GetNames<TEnum>()
+            .FirstOrDefault(name => string.Equals(name, trimmed, StringComparison.OrdinalIgnoreCase));
+        return definedName is not null && Enum.TryParse(definedName, out parsed);
+    }
+}
