+public static class JobTrackCommandApp
+{
+    public static ICommandApp Create(IJobTrackApiClient? client = null, IConsoleWriter? console = null)
+    {
+        var registrar = new TypeRegistrar();
+        registrar.RegisterInstance(typeof(IJobTrackApiClient), client ?? new JobTrackApiClient());
+        registrar.RegisterInstance(typeof(IConsoleWriter), console ?? new SystemConsoleWriter());
+
+        var app = new CommandApp(registrar);
+        app.Configure(config =>
+        {
+            config.SetApplicationName("jt");
+            config.SetApplicationVersion("0.1.0");
+
+            config.AddBranch("task", task =>
+            {
+                task.SetDescription("Work with tasks.");
+                task.AddCommand<TaskListCommand>("list").WithDescription("List tasks.");
+                task.AddCommand<TaskCommentsCommand>("comments").WithDescription("List comments for a task.");
+            });
+
+            config.AddBranch("project", project =>
+            {
+                project.SetDescription("Work with projects.");
+                project.AddCommand<ProjectListCommand>("list").WithDescription("List projects.");
+            });
+
+            config.AddCommand<WhoamiCommand>("whoami").WithDescription("Show the authenticated principal.");
+        });
+
+        return app;
+    }
