+
+public enum JobTrackReadDataKind
+{
+    Empty,
+    Json,
+    Text
+}
+
+public interface IJobTrackReadData
+{
+    bool IsEmpty { get; }
+
+    JobTrackReadDataKind Kind { get; }
+
+    string Content { get; }
+}
+
+public static class JobTrackReadData
+{
+    public static IJobTrackReadData Empty => JobTrackResult.Empty;
+
+    public static IJobTrackReadData FromJson(string? value)
+    {
+        return JobTrackResult.FromJson(value);
+    }
+
+    public static IJobTrackReadData FromText(string? value)
+    {
+        return JobTrackResult.FromText(value);
+    }
+}
+
+internal sealed class JobTrackResult : IJobTrackReadData
+{
+    private JobTrackResult(JobTrackReadDataKind kind, string content)
+    {
+        Kind = kind;
+        Content = content;
+    }
+
+    internal static JobTrackResult Empty { get; } = new(JobTrackReadDataKind.Empty, string.Empty);
+
+    public bool IsEmpty => Kind == JobTrackReadDataKind.Empty || string.IsNullOrWhiteSpace(Content);
+
+    public JobTrackReadDataKind Kind { get; }
+
+    public string Content { get; }
+
+    internal static JobTrackResult FromJson(string? value)
+    {
+        if (string.IsNullOrWhiteSpace(value))
+        {
+            return Empty;
+        }
+
+        using var document = JsonDocument.Parse(value);
+        return new JobTrackResult(JobTrackReadDataKind.Json, document.RootElement.GetRawText());
+    }
+
+    internal static JobTrackResult FromText(string? value)
+    {
+        return string.IsNullOrWhiteSpace(value)
+            ? Empty
