   144	    private async Task<IJobTrackReadData> GetDataAsync(
   145	        string path,
   146	        IReadOnlyList<QueryParameter> query,
   147	        CancellationToken cancellationToken = default)
   148	    {
   149	        var (baseUri, key) = ReadEnv();
   150	        using var http = NewClient(baseUri, key);
   151	
   152	        try
   153	        {
   154	            using var response = await http.GetAsync(BuildPath(path, query), HttpCompletionOption.ResponseHeadersRead, cancellationToken);
   155	            var body = await ReadContentAsync(response.Content, cancellationToken);
   156	
   157	            if (!response.IsSuccessStatusCode)
   158	            {
   159	                throw new JobTrackApiException(
   160	                    FormatFailureMessage(response),
   161	                    BuildFailureDetails(response, body));
   162	            }
   163	
   164	            return ParseResponseBody(body);
   165	        }
   166	        catch (Exception ex) when (ex is HttpRequestException or IOException)
   167	        {
   168	            throw new JobTrackApiRequestException(ex.Message, ex);
   169	        }
   170	    }
