   172	    private static string FormatFailureMessage(HttpResponseMessage response)
   173	    {
   174	        var status = $"HTTP {(int)response.StatusCode}";
   175	        return string.IsNullOrWhiteSpace(response.ReasonPhrase)
   176	            ? status
   177	            : $"{status} {response.ReasonPhrase}";
   178	    }
   179	
   180	    private static IJobTrackReadData BuildFailureDetails(HttpResponseMessage response, string body)
   181	    {
   182	        var details = new Dictionary<string, object?>(StringComparer.Ordinal);
   183	
   184	        if (!string.IsNullOrWhiteSpace(response.ReasonPhrase))
   185	        {
   186	            details["reason"] = response.ReasonPhrase;
   187	        }
   188	
   189	        if (!string.IsNullOrWhiteSpace(body))
   190	        {
   191	            details["detail"] = ReadStructuredDetail(body);
   192	        }
   193	
   194	        return details.Count == 0
   195	            ? JobTrackReadData.Empty
   196	            : JobTrackReadData.FromJson(JsonSerializer.Serialize(details));
   197	    }
