   213	    {
   214	        if (string.IsNullOrWhiteSpace(body))
   215	        {
   216	            return JobTrackReadData.Empty;
   217	        }
   218	
   219	        try
   220	        {
   221	            return JobTrackReadData.FromJson(body);
   222	        }
   223	        catch (JsonException ex)
