   229	    private static async Task<string> ReadContentAsync(HttpContent content, CancellationToken cancellationToken)
   230	    {
   231	        if (content.Headers.ContentLength is > MaxResponseBytes)
   232	        {
   233	            throw new JobTrackApiResponseException($"JobTrack API response exceeded {MaxResponseBytes} bytes");
   234	        }
   235	
   236	        await using var responseStream = await content.ReadAsStreamAsync(cancellationToken);
   237	        using var buffer = new MemoryStream();
   238	        var chunk = new byte[ResponseReadBufferBytes];
   239	
   240	        while (true)
   241	        {
   242	            var read = await responseStream.ReadAsync(chunk, cancellationToken);
   243	            if (read == 0)
   244	            {
   245	                break;
   246	            }
   247	
   248	            if (buffer.Length + read > MaxResponseBytes)
   249	            {
   250	                throw new JobTrackApiResponseException($"JobTrack API response exceeded {MaxResponseBytes} bytes");
   251	            }
   252	
   253	            buffer.Write(chunk, 0, read);
   254	        }
   255	
   256	        return Encoding.UTF8.GetString(buffer.ToArray());
   257	    }
   258	
   259	    private static string BuildPath(string path, IReadOnlyList<QueryParameter> query)
   260	    {
   261	        var pairs = query
   262	            .Where(parameter => !string.IsNullOrWhiteSpace(parameter.Value))
   263	            .Select(parameter => $"{Encode(parameter.Name)}={Encode(parameter.Value!)}")
   264	            .ToArray();
   265	
   266	        return pairs.Length == 0 ? path : $"{path}?{string.Join("&", pairs)}";
   267	    }
