   269	    private static (Uri BaseUri, string Key) ReadEnv()
   270	    {
   271	        var url = Environment.GetEnvironmentVariable(ApiUrlEnv);
   272	        var key = Environment.GetEnvironmentVariable(ApiKeyEnv);
   273	
   274	        if (string.IsNullOrWhiteSpace(url))
   275	        {
   276	            throw new JobTrackConfigurationException($"{ApiUrlEnv} must be set (e.g. https://jobtrack.example.com or http://localhost:5000)");
   277	        }
   278	
   279	        if (string.IsNullOrWhiteSpace(key))
   280	        {
   281	            throw new JobTrackConfigurationException($"{ApiKeyEnv} must be set");
   282	        }
   283	
   284	        var trimmedUrl = url.Trim().TrimEnd('/');
   285	        if (!Uri.TryCreate(trimmedUrl, UriKind.Absolute, out var baseUri) ||
   286	            (baseUri.Scheme != Uri.UriSchemeHttps && baseUri.Scheme != Uri.UriSchemeHttp))
   287	        {
   288	            throw new JobTrackConfigurationException($"{ApiUrlEnv} must be an absolute http or https URL");
   289	        }
   290	
   291	        if (baseUri.Scheme == Uri.UriSchemeHttp && !baseUri.IsLoopback)
   292	        {
   293	            throw new JobTrackConfigurationException($"{ApiUrlEnv} must use https unless it points to localhost for development");
   294	        }
   295	
   296	        return (baseUri, key.Trim());
   297	    }
