   299	    private HttpClient NewClient(Uri baseUri, string key)
   300	    {
   301	        var http = _handler is null
   302	            ? new HttpClient()
   303	            : new HttpClient(_handler, disposeHandler: false);
   304	
   305	        http.BaseAddress = baseUri;
   306	        http.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", key);
   307	        http.DefaultRequestHeaders.UserAgent.ParseAdd("jt/0.1");
   308	        return http;
   309	    }
